"use client";

import { Drawer as DrawerPrimitive } from "@base-ui/react/drawer";
import { cn } from "cn";
import * as React from "react";
import { useBottomSheetController } from "@/hooks/use-bottom-sheet-controller";
import type {
  BottomSheetDetents,
  BottomSheetLayout,
  BottomSheetSize,
} from "@/lib/bottom-sheet";
import { withGlass } from "@/lib/glass/with-glass";
import { type FeedbackOption, useFeedback } from "@/components/ui/feedback";

type BottomSheetShape = Pick<BottomSheetLayout, "expandable" | "full">;

type BottomSheetContextProps = BottomSheetShape & {
  open: boolean;
  modal: DrawerPrimitive.Root.Props["modal"];
  size: BottomSheetSize;
  /** At `"lg"` on an expandable sheet, or a single sheet at full height. */
  expanded: boolean;
  setSize: (size: BottomSheetSize) => void;
  toggle: () => void;
  close: () => void;
  isOpen: () => boolean;
  setShape: (shape: BottomSheetShape) => void;
  detents: BottomSheetDetents;
  keyboard: "resize" | "lift";
  footerMode: "adaptive" | "fixed";
  expandOnInputFocus: boolean;
  contentKey: React.Key | undefined;
  labels: { expand: string; collapse: string };
};

const BottomSheetContext = React.createContext<BottomSheetContextProps | null>(
  null,
);

function useBottomSheet() {
  const context = React.useContext(BottomSheetContext);
  if (!context) {
    throw new Error("useBottomSheet must be used within a BottomSheet.");
  }
  return context;
}

type BottomSheetProps = Omit<
  DrawerPrimitive.Root.Props,
  | "snapPoints"
  | "snapPoint"
  | "defaultSnapPoint"
  | "onSnapPointChange"
  | "snapToSequentialPoints"
  | "swipeDirection"
> & {
  /** `"auto"` offers `"lg"` only once content outgrows the default size. */
  detents?: BottomSheetDetents;
  size?: BottomSheetSize;
  defaultSize?: BottomSheetSize;
  onSizeChange?: (size: BottomSheetSize) => void;
  /** Expands an expandable sheet when a text field inside it takes focus. */
  expandOnInputFocus?: boolean;
  /** `"resize"` fits the keyboard's space; `"lift"` keeps height and rises. */
  keyboard?: "resize" | "lift";
  /** `"adaptive"` scrolls the footer with the body once both no longer fit. */
  footerMode?: "adaptive" | "fixed";
  /** A new key returns the sheet to its default size, scrolled to the top. */
  contentKey?: React.Key;
  labels?: { expand?: string; collapse?: string };
  feedback?: FeedbackOption;
};

function BottomSheet({
  open: openProp,
  defaultOpen = false,
  modal = true,
  onOpenChange,
  onOpenChangeComplete,
  actionsRef,
  detents = "auto",
  size: sizeProp,
  defaultSize = "default",
  onSizeChange,
  expandOnInputFocus = true,
  keyboard = "resize",
  footerMode = "adaptive",
  contentKey,
  labels,
  feedback,
  ...props
}: BottomSheetProps) {
  const trigger = useFeedback(feedback);
  const [_open, _setOpen] = React.useState(defaultOpen);
  const open = openProp ?? _open;
  const openRef = React.useRef(open);
  openRef.current = open;
  const [_size, _setSize] = React.useState(defaultSize);
  const size = sizeProp ?? _size;
  const [shape, setShapeState] = React.useState<BottomSheetShape>({
    expandable: false,
    full: false,
  });
  const actions = React.useRef<DrawerPrimitive.Root.Actions | null>(null);
  React.useImperativeHandle(
    actionsRef,
    () => ({
      close: () => actions.current?.close(),
      unmount: () => actions.current?.unmount(),
    }),
    [],
  );

  const setSize = React.useCallback(
    (value: BottomSheetSize) => {
      if (sizeProp === undefined) _setSize(value);
      onSizeChange?.(value);
      // A detent change taps back; the reset after closing stays silent.
      if (openRef.current) trigger("light");
    },
    [sizeProp, onSizeChange, trigger],
  );
  const setShape = React.useCallback((value: BottomSheetShape) => {
    setShapeState((current) =>
      current.expandable === value.expandable && current.full === value.full
        ? current
        : value,
    );
  }, []);

  const contextValue = React.useMemo<BottomSheetContextProps>(
    () => ({
      ...shape,
      open,
      modal,
      size,
      expanded: shape.full || (shape.expandable && size === "lg"),
      setSize,
      toggle: () => setSize(size === "lg" ? "default" : "lg"),
      close: () => actions.current?.close(),
      isOpen: () => openRef.current,
      setShape,
      detents,
      keyboard,
      footerMode,
      expandOnInputFocus,
      contentKey,
      labels: {
        expand: labels?.expand ?? "Expand sheet",
        collapse: labels?.collapse ?? "Collapse sheet",
      },
    }),
    [
      shape,
      open,
      modal,
      size,
      setSize,
      setShape,
      detents,
      keyboard,
      footerMode,
      expandOnInputFocus,
      contentKey,
      labels?.expand,
      labels?.collapse,
    ],
  );

  return (
    <BottomSheetContext.Provider value={contextValue}>
      <DrawerPrimitive.Root
        data-slot="bottom-sheet"
        swipeDirection="down"
        modal={modal}
        open={open}
        onOpenChange={(value, details) => {
          onOpenChange?.(value, details);
          if (openProp === undefined && !details.isCanceled) _setOpen(value);
        }}
        onOpenChangeComplete={(value) => {
          // The next opening starts from the default size again.
          if (!value) setSize(defaultSize);
          onOpenChangeComplete?.(value);
        }}
        actionsRef={actions}
        {...props}
      />
    </BottomSheetContext.Provider>
  );
}

function BottomSheetTrigger(props: DrawerPrimitive.Trigger.Props) {
  return (
    <DrawerPrimitive.Trigger data-slot="bottom-sheet-trigger" {...props} />
  );
}

function BottomSheetPortal(props: DrawerPrimitive.Portal.Props) {
  return <DrawerPrimitive.Portal data-slot="bottom-sheet-portal" {...props} />;
}

function BottomSheetClose(props: DrawerPrimitive.Close.Props) {
  return <DrawerPrimitive.Close data-slot="bottom-sheet-close" {...props} />;
}

function BottomSheetOverlay({
  className,
  ...props
}: DrawerPrimitive.Backdrop.Props) {
  return (
    <DrawerPrimitive.Backdrop
      data-slot="bottom-sheet-overlay"
      className={cn(
        "fixed inset-0 z-50 min-h-dvh select-none bg-black/30 opacity-[calc((0.6+0.4*var(--bottom-sheet-progress,0))*(1-var(--bottom-sheet-dismiss,0)))] transition-opacity duration-500 ease-[cubic-bezier(0.32,0.72,0,1)] data-ending-style:opacity-0 data-starting-style:opacity-0 data-dragging:duration-0 data-ending-style:duration-300 data-gliding:duration-0 supports-[-webkit-touch-callout:none]:absolute supports-backdrop-filter:backdrop-blur-xs motion-reduce:duration-0",
        className,
      )}
      {...props}
    />
  );
}

function BottomSheetContentImplementation({
  className,
  children,
  showGrabber = true,
  ...props
}: DrawerPrimitive.Popup.Props & { showGrabber?: boolean }) {
  const sheet = useBottomSheet();
  const { popupRef, containerRef, overlayRef, probeRef } =
    useBottomSheetController(sheet);
  // Keep the last content while the sheet animates out, so clearing data in
  // the parent cannot flash an empty sheet.
  const lastChildren = React.useRef(children);
  if (sheet.open) lastChildren.current = children;

  return (
    <BottomSheetPortal>
      {/* A nonmodal sheet leaves the page behind it usable. */}
      {sheet.modal === true && <BottomSheetOverlay ref={overlayRef} />}
      {/* Base UI keeps modality, focus and dismissal; the sheet runs its own
          size gestures, so Base UI's swipe handling stays out. */}
      <DrawerPrimitive.Viewport
        data-slot="bottom-sheet-viewport"
        data-base-ui-swipe-ignore=""
        className="pointer-events-none fixed inset-0 z-50 [--bottom-sheet-top-gap:calc(env(safe-area-inset-top,0px)+0.75rem)]"
      >
        <div
          ref={probeRef}
          aria-hidden="true"
          data-slot="bottom-sheet-probe"
          className="pointer-events-none invisible absolute top-0 h-(--bottom-sheet-top-gap) w-0"
        />
        <DrawerPrimitive.Popup
          ref={popupRef}
          data-slot="bottom-sheet-popup"
          data-size={sheet.size}
          data-expanded={sheet.expanded ? "" : undefined}
          data-expandable={sheet.expandable ? "" : undefined}
          className={cn(
            cn(
              "pointer-events-auto absolute mx-auto flex max-w-(--bottom-sheet-max-width) flex-col overflow-hidden rounded-(--bottom-sheet-radius) border border-popover bg-popover text-popover-foreground text-sm shadow-xl outline-none will-change-transform dark:border-border",
              // Compact floats with a margin on each side and below; it fades
              // out while expanding, so the expanded sheet meets the edges.
              "[--bottom-sheet-gap:--spacing(2)] [--bottom-sheet-margin:calc(var(--bottom-sheet-gap)*(1-var(--bottom-sheet-progress)))] [--bottom-sheet-max-width:none] [--bottom-sheet-radius:var(--radius-5xl)] [--bottom-sheet-safe-bottom:max(0px,env(safe-area-inset-bottom,0px)-var(--bottom-sheet-margin))]",
              "right-[calc(var(--bottom-sheet-margin)+env(safe-area-inset-right,0px))] bottom-[calc(var(--bottom-sheet-keyboard,0px)+var(--bottom-sheet-margin))] left-[calc(var(--bottom-sheet-margin)+env(safe-area-inset-left,0px))] h-(--bottom-sheet-height,auto)",
              "transform-[translate3d(0,var(--bottom-sheet-offset,0px),0)] transition-[transform,bottom] duration-500 ease-[cubic-bezier(0.32,0.72,0,1)] data-gliding:transition-[bottom] data-dragging:duration-0 motion-reduce:duration-0",
              "data-ending-style:transform-[translate3d(0,calc(100%+var(--bottom-sheet-margin)+2px),0)] data-starting-style:transform-[translate3d(0,calc(100%+var(--bottom-sheet-margin)+2px),0)] data-ending-style:duration-300",
              // Glass turns opaque while expanding, so a full sheet reads as
              // a solid page.
              "glass:before:pointer-events-none glass:before:absolute glass:before:inset-0 glass:before:-z-1 glass:before:rounded-[inherit] glass:before:bg-popover glass:before:opacity-(--bottom-sheet-progress)",
            ),
            className,
          )}
          {...props}
        >
          {showGrabber && <BottomSheetGrabber />}
          {/* The body scrolls between the header and footer; when space runs
              short, the whole container scrolls instead. */}
          <div
            ref={containerRef}
            data-slot="bottom-sheet-container"
            className="group/bottom-sheet-container data-[scroll=container]:scroll-fade-y flex min-h-0 flex-1 flex-col overflow-hidden overscroll-contain not-has-[>[data-slot=bottom-sheet-header]]:pt-5 not-has-[>[data-slot=bottom-sheet-footer]]:pb-(--bottom-sheet-safe-bottom) [overflow-anchor:none] data-[scroll=container]:overflow-y-auto"
          >
            {sheet.open ? children : lastChildren.current}
          </div>
        </DrawerPrimitive.Popup>
      </DrawerPrimitive.Viewport>
    </BottomSheetPortal>
  );
}

function BottomSheetGrabber({
  className,
  ...props
}: React.ComponentProps<"button">) {
  const { size, expandable, toggle, labels } = useBottomSheet();
  return (
    <button
      type="button"
      data-slot="bottom-sheet-grabber"
      aria-label={size === "lg" ? labels.collapse : labels.expand}
      aria-hidden={expandable ? undefined : true}
      disabled={!expandable}
      className={cn(
        "absolute inset-x-0 top-0 z-20 flex h-5 cursor-grab touch-none items-start justify-center rounded-t-[inherit] pt-1.5 outline-none after:h-1.25 after:w-9 after:rounded-full after:bg-foreground/20 after:transition-colors hover:after:bg-foreground/30 focus-visible:after:bg-ring active:cursor-grabbing",
        className,
      )}
      onClick={toggle}
      {...props}
    />
  );
}

function BottomSheetHeader({
  className,
  collapseOnScroll = false,
  ...props
}: React.ComponentProps<"div"> & { collapseOnScroll?: boolean }) {
  return (
    <div
      data-slot="bottom-sheet-header"
      data-collapse-on-scroll={collapseOnScroll}
      className={cn(
        "group/bottom-sheet-header relative flex shrink-0 touch-none select-none flex-col gap-1 px-5 pt-6 pb-3",
        className,
      )}
      {...props}
    />
  );
}

function BottomSheetTitle({
  className,
  ...props
}: DrawerPrimitive.Title.Props) {
  return (
    <DrawerPrimitive.Title
      data-slot="bottom-sheet-title"
      className={cn(
        "font-heading font-semibold text-base text-foreground",
        className,
      )}
      {...props}
    />
  );
}

function BottomSheetDescription({
  className,
  ...props
}: DrawerPrimitive.Description.Props) {
  return (
    <DrawerPrimitive.Description
      data-slot="bottom-sheet-description"
      className={cn(
        "max-h-24 overflow-hidden text-muted-foreground text-sm transition-[max-height,opacity] duration-200 group-data-collapsed/bottom-sheet-header:max-h-0 group-data-collapsed/bottom-sheet-header:opacity-0",
        className,
      )}
      {...props}
    />
  );
}

function BottomSheetBody({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="bottom-sheet-body"
      className={cn(
        // Content fades under the header and footer while more remains.
        "scroll-fade-y group-data-[scroll=container]/bottom-sheet-container:mask-none flex min-h-0 shrink flex-col gap-4 overflow-hidden overscroll-contain px-5 pb-4 group-data-[scroll=container]/bottom-sheet-container:shrink-0 group-data-[scroll=body]/bottom-sheet-container:overflow-y-auto",
        className,
      )}
      {...props}
    />
  );
}

function BottomSheetFooter({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="bottom-sheet-footer"
      className={cn(
        "mt-auto flex shrink-0 flex-col gap-2 px-5 pt-3 pb-[calc(--spacing(4)+var(--bottom-sheet-safe-bottom))]",
        className,
      )}
      {...props}
    />
  );
}

function BottomSheetExpandedContent(props: React.ComponentProps<"div">) {
  const { expanded } = useBottomSheet();
  return (
    <div
      data-slot="bottom-sheet-expanded-content"
      hidden={!expanded}
      {...props}
    />
  );
}

const BottomSheetContent = withGlass(BottomSheetContentImplementation);

export type { BottomSheetDetents, BottomSheetSize } from "@/lib/bottom-sheet";
export {
  BottomSheet,
  BottomSheetBody,
  BottomSheetClose,
  BottomSheetContent,
  BottomSheetDescription,
  BottomSheetExpandedContent,
  BottomSheetFooter,
  BottomSheetGrabber,
  BottomSheetHeader,
  BottomSheetOverlay,
  BottomSheetPortal,
  type BottomSheetProps,
  BottomSheetTitle,
  BottomSheetTrigger,
  useBottomSheet,
};

"use client";

import { Button as ButtonPrimitive } from "@base-ui/react/button";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "cn";
import { withGlass } from "@/lib/glass/with-glass";
import { type FeedbackOption, useFeedback } from "@/components/ui/feedback";

const buttonVariants = cva(
  "group/button inline-flex shrink-0 select-none items-center justify-center whitespace-nowrap rounded-4xl border border-transparent bg-clip-padding font-medium text-sm outline-none transition-[box-shadow,scale] duration-150 ease-out focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/30 disabled:pointer-events-none disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-3 aria-invalid:ring-destructive/20 motion-safe:active:not-aria-[haspopup]:scale-[1.04] dark:aria-invalid:border-destructive/50 dark:aria-invalid:ring-destructive/40 [&_svg:not([class*='size-'])]:size-4 [&_svg]:pointer-events-none [&_svg]:shrink-0",
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground hover:bg-primary/80",
        outline:
          "border-border bg-background hover:bg-muted hover:text-foreground aria-expanded:bg-muted aria-expanded:text-foreground dark:bg-transparent dark:hover:bg-input/30",
        secondary:
          "bg-secondary text-secondary-foreground hover:bg-[color-mix(in_oklch,var(--secondary),var(--foreground)_5%)] aria-expanded:bg-secondary aria-expanded:text-secondary-foreground",
        ghost:
          "hover:bg-muted hover:text-foreground aria-expanded:bg-muted aria-expanded:text-foreground dark:hover:bg-muted/50",
        destructive:
          "bg-destructive/10 text-destructive-foreground hover:bg-destructive/20 focus-visible:border-destructive/40 focus-visible:ring-destructive/20 dark:bg-destructive/20 dark:focus-visible:ring-destructive/40 dark:hover:bg-destructive/30",
        link: "text-accent-foreground underline-offset-4 hover:underline",
      },
      size: {
        default:
          "h-9 gap-1.5 px-3 has-data-[icon=inline-start]:ps-2.5 has-data-[icon=inline-end]:pe-2.5",
        xs: "h-6 gap-1 px-2.5 has-data-[icon=inline-start]:ps-2 has-data-[icon=inline-end]:pe-2 [&_svg:not([class*='size-'])]:size-3",
        sm: "h-8 gap-1 px-3 has-data-[icon=inline-start]:ps-2 has-data-[icon=inline-end]:pe-2",
        lg: "h-10 gap-1.5 px-4 has-data-[icon=inline-start]:ps-3 has-data-[icon=inline-end]:pe-3",
        icon: "size-9",
        "icon-xs": "size-6 [&_svg:not([class*='size-'])]:size-3",
        "icon-sm": "size-8",
        "icon-lg": "size-10",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  },
);

function ButtonImplementation({
  className,
  variant = "default",
  size = "default",
  feedback,
  onClick,
  ...props
}: ButtonPrimitive.Props &
  VariantProps<typeof buttonVariants> & { feedback?: FeedbackOption }) {
  // Plain buttons stay quiet unless asked, as on Apple platforms.
  const trigger = useFeedback(feedback, { optIn: true });
  return (
    <ButtonPrimitive
      data-slot="button"
      data-variant={variant}
      className={cn(buttonVariants({ variant, size }), className)}
      onClick={(event) => {
        onClick?.(event);
        trigger(variant === "destructive" ? "medium" : "light");
      }}
      {...props}
    />
  );
}

const Button = withGlass(ButtonImplementation);

export { Button, buttonVariants };

"use client";

import { Button, buttonVariants } from "@/components/ui/button";
import { cn } from "cn";
import {
  ChevronDownIcon,
  ChevronLeftIcon,
  ChevronRightIcon,
} from "lucide-react";
import * as React from "react";
import {
  type DayButton,
  DayPicker,
  getDefaultClassNames,
  type Locale,
} from "react-day-picker";

const CalendarLocaleContext = React.createContext<Partial<Locale> | undefined>(
  undefined,
);

function CalendarRoot({
  className,
  rootRef,
  ...props
}: React.ComponentProps<
  NonNullable<
    NonNullable<React.ComponentProps<typeof DayPicker>["components"]>["Root"]
  >
>) {
  return (
    <div
      data-slot="calendar"
      ref={rootRef}
      className={cn(className)}
      {...props}
    />
  );
}

function CalendarChevron({
  className,
  orientation,
  ...props
}: React.ComponentProps<
  NonNullable<
    NonNullable<React.ComponentProps<typeof DayPicker>["components"]>["Chevron"]
  >
>) {
  if (orientation === "left")
    return (
      <ChevronLeftIcon
        className={cn("size-4 rtl:rotate-180", className)}
        {...props}
      />
    );
  if (orientation === "right")
    return (
      <ChevronRightIcon
        className={cn("size-4 rtl:rotate-180", className)}
        {...props}
      />
    );
  return <ChevronDownIcon className={cn("size-4", className)} {...props} />;
}

function CalendarWeekNumber({
  children,
  ...props
}: React.ComponentProps<
  NonNullable<
    NonNullable<
      React.ComponentProps<typeof DayPicker>["components"]
    >["WeekNumber"]
  >
>) {
  return (
    <td {...props}>
      <div className="flex size-(--cell-size) items-center justify-center text-center">
        {children}
      </div>
    </td>
  );
}

function Calendar({
  className,
  classNames,
  showOutsideDays = true,
  captionLayout = "label",
  buttonVariant = "ghost",
  locale,
  formatters,
  components,
  ...props
}: React.ComponentProps<typeof DayPicker> & {
  buttonVariant?: React.ComponentProps<typeof Button>["variant"];
}) {
  const defaultClassNames = getDefaultClassNames();

  return (
    <CalendarLocaleContext value={locale}>
      <DayPicker
        showOutsideDays={showOutsideDays}
        className={cn(
          "group/calendar bg-background in-data-[slot=card-content]:bg-transparent in-data-[slot=popover-content]:bg-transparent p-3 [--cell-radius:var(--radius-4xl)] [--cell-size:--spacing(8)]",
          String.raw`rtl:**:[.rdp-button\_next>svg]:rotate-180`,
          String.raw`rtl:**:[.rdp-button\_previous>svg]:rotate-180`,
          className,
        )}
        captionLayout={captionLayout}
        locale={locale}
        formatters={{
          formatMonthDropdown: (date) =>
            date.toLocaleString(locale?.code ?? "en-US", { month: "short" }),
          ...formatters,
        }}
        classNames={{
          root: cn("w-fit", defaultClassNames.root),
          months: cn(
            "relative flex flex-col gap-4 md:flex-row",
            defaultClassNames.months,
          ),
          month: cn("flex w-full flex-col gap-4", defaultClassNames.month),
          nav: cn(
            "absolute inset-x-0 top-0 flex w-full items-center justify-between gap-1",
            defaultClassNames.nav,
          ),
          button_previous: cn(
            buttonVariants({ variant: buttonVariant }),
            "size-(--cell-size) select-none p-0 aria-disabled:opacity-50",
            defaultClassNames.button_previous,
          ),
          button_next: cn(
            buttonVariants({ variant: buttonVariant }),
            "size-(--cell-size) select-none p-0 aria-disabled:opacity-50",
            defaultClassNames.button_next,
          ),
          month_caption: cn(
            "flex h-(--cell-size) w-full items-center justify-center px-(--cell-size)",
            defaultClassNames.month_caption,
          ),
          dropdowns: cn(
            "flex h-(--cell-size) w-full items-center justify-center gap-1.5 font-medium text-sm",
            defaultClassNames.dropdowns,
          ),
          dropdown_root: cn(
            "relative rounded-(--cell-radius)",
            defaultClassNames.dropdown_root,
          ),
          dropdown: cn(
            "absolute inset-0 bg-popover opacity-0",
            defaultClassNames.dropdown,
          ),
          caption_label: cn(
            "select-none font-medium",
            captionLayout === "label"
              ? "text-sm"
              : "flex items-center gap-1 rounded-(--cell-radius) text-sm [&>svg]:size-3.5 [&>svg]:text-muted-foreground",
            defaultClassNames.caption_label,
          ),
          month_grid: cn(
            "w-full border-collapse",
            defaultClassNames.month_grid,
          ),
          weekdays: cn("flex", defaultClassNames.weekdays),
          weekday: cn(
            "flex-1 select-none rounded-(--cell-radius) font-normal text-[0.8rem] text-muted-foreground",
            defaultClassNames.weekday,
          ),
          week: cn("mt-2 flex w-full", defaultClassNames.week),
          week_number_header: cn(
            "w-(--cell-size) select-none",
            defaultClassNames.week_number_header,
          ),
          week_number: cn(
            "select-none text-[0.8rem] text-muted-foreground",
            defaultClassNames.week_number,
          ),
          day: cn(
            "group/day relative aspect-square h-full w-full select-none rounded-(--cell-radius) p-0 text-center [&:last-child[data-selected=true]_button]:rounded-e-(--cell-radius)",
            props.showWeekNumber
              ? "[&:nth-child(2)[data-selected=true]_button]:rounded-s-(--cell-radius)"
              : "[&:first-child[data-selected=true]_button]:rounded-s-(--cell-radius)",
            defaultClassNames.day,
          ),
          range_start: cn(
            "relative isolate z-0 rounded-s-(--cell-radius) bg-accent after:absolute after:inset-e-0 after:inset-y-0 after:w-4 after:bg-accent",
            defaultClassNames.range_start,
          ),
          range_middle: cn("rounded-none", defaultClassNames.range_middle),
          range_end: cn(
            "relative isolate z-0 rounded-e-(--cell-radius) bg-accent after:absolute after:inset-s-0 after:inset-y-0 after:w-4 after:bg-accent",
            defaultClassNames.range_end,
          ),
          today: cn(
            // A single selected day is a round button; the square cell
            // behind it stays clear. Inside a range the cell is the band.
            "rounded-(--cell-radius) bg-accent text-accent-foreground has-data-[selected-single=true]:bg-transparent data-[selected=true]:rounded-none",
            defaultClassNames.today,
